   505→void UWjWorldCurrencySubsystem::PollGemPurchaseResult()
   506→{
   507→#if WITH_STEAM
   508→	if (!bGemPurchasePending)
   509→	{
   510→		StopGemPurchasePolling();
   511→		return;
   512→	}
   513→
   514→	// Gem 팩 구매는 Steam 오버레이를 통해 처리되므로
   515→	// 인벤토리 변경을 감지하여 완료 판단
   516→	// CosmeticSubsystem의 OnInventoryUpdated → HandleInventoryUpdated → RefreshBalancesFromInventory
   517→	// 에서 Gem 잔액 변경이 감지되면 구매 완료로 판단
   518→
   519→	// 간단한 타임아웃 처리 (300초)
   520→	static float GemPurchaseStartTime = 0.0f;
   521→	UWorld* World = GetWorld();
   522→	if (World)
   523→	{
   524→		if (GemPurchaseStartTime == 0.0f)
   525→		{
   526→			GemPurchaseStartTime = World->GetTimeSeconds();
   527→		}
   528→
   529→		float ElapsedTime = World->GetTimeSeconds() - GemPurchaseStartTime;
   530→		if (ElapsedTime > 300.0f)
   531→		{
   532→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매 타임아웃"));
   533→			bGemPurchasePending = false;
   534→			GemPurchaseStartTime = 0.0f;
   535→			StopGemPurchasePolling();
   536→		}
   537→	}
   538→#else
   539→	StopGemPurchasePolling();
   540→#endif
   541→}
