   415→void UCosmeticMainWindow::RefreshDetailInfo()
   416→{
   417→	if (SelectedItemId.IsNone())
   418→	{
   419→		if (SelectedItemNameText)
   420→		{
   421→			SelectedItemNameText->SetText(FText::GetEmpty());
   422→		}
   423→		if (SelectedItemDescriptionText)
   424→		{
   425→			SelectedItemDescriptionText->SetText(FText::GetEmpty());
   426→		}
   427→		if (SelectedItemPriceText)
   428→		{
   429→			SelectedItemPriceText->SetText(FText::GetEmpty());
   430→		}
   431→		return;
   432→	}
   433→
   434→	UGameInstance* GI = GetGameInstance();
   435→	if (!GI)
   436→	{
   437→		return;
   438→	}
   439→
   440→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   441→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   442→	{
   443→		return;
   444→	}
   445→
   446→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(SelectedItemId);
   447→	if (!ItemDef)
   448→	{
   449→		return;
   450→	}
   451→
   452→	if (SelectedItemNameText)
   453→	{
   454→		SelectedItemNameText->SetText(ItemDef->DisplayName);
   455→	}
   456→
   457→	if (SelectedItemDescriptionText)
   458→	{
   459→		SelectedItemDescriptionText->SetText(ItemDef->Description);
   460→	}
   461→
   462→	if (SelectedItemPriceText)
   463→	{
   464→		if (CosmeticSub->HasItem(SelectedItemId))
   465→		{
   466→			SelectedItemPriceText->SetText(NSLOCTEXT("Cosmetic", "Owned", "보유중"));
   467→		}
   468→		else if (ItemDef->CoinPrice > 0 && ItemDef->GemPrice > 0)
   469→		{
   470→			SelectedItemPriceText->SetText(FText::Format(
   471→				NSLOCTEXT("Cosmetic", "CoinGemPriceFormat", "{0} Coin / {1} Gem"),
   472→				FText::AsNumber(ItemDef->CoinPrice), FText::AsNumber(ItemDef->GemPrice)));
   473→		}
   474→		else if (ItemDef->CoinPrice > 0)
   475→		{
   476→			SelectedItemPriceText->SetText(FText::Format(
   477→				NSLOCTEXT("Cosmetic", "CoinPriceFormat", "{0} Coin"),
   478→				FText::AsNumber(ItemDef->CoinPrice)));
   479→		}
   480→		else if (ItemDef->GemPrice > 0)
   481→		{
   482→			SelectedItemPriceText->SetText(FText::Format(
   483→				NSLOCTEXT("Cosmetic", "GemPriceFormat", "{0} Gem"),
   484→				FText::AsNumber(ItemDef->GemPrice)));
   485→		}
   486→		else
   487→		{
   488→			SelectedItemPriceText->SetText(NSLOCTEXT("Cosmetic", "Free", "무료"));
   489→		}
   490→	}
   491→}
