   571→	FString ConfigFilePath = FPaths::GeneratedConfigDir() + TEXT("CurrencyBalance.ini");
   572→
   573→	GConfig->SetInt(*CurrencyConfigSection, TEXT("CoinBalance"), CoinBalance, ConfigFilePath);
   574→	GConfig->SetInt(*CurrencyConfigSection, TEXT("GemBalance"), GemBalance, ConfigFilePath);
   575→
   576→	GConfig->Flush(false, ConfigFilePath);
