   580→void UWjWorldCurrencySubsystem::LoadBalancesFromLocal()
   581→{
   582→	FString ConfigFilePath = FPaths::GeneratedConfigDir() + TEXT("CurrencyBalance.ini");
   583→
   584→	int32 LoadedCoin = 0;
   585→	int32 LoadedGem = 0;
   586→
   587→	GConfig->GetInt(*CurrencyConfigSection, TEXT("CoinBalance"), LoadedCoin, ConfigFilePath);
   588→	GConfig->GetInt(*CurrencyConfigSection, TEXT("GemBalance"), LoadedGem, ConfigFilePath);
   589→
   590→	CoinBalance = FMath::Max(0, LoadedCoin);
   591→	GemBalance = FMath::Max(0, LoadedGem);
   592→
   593→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 로드 완료 (Coin: %d, Gem: %d)"), CoinBalance, GemBalance);
