   596→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   597→{
   598→	NewAmount = FMath::Max(0, NewAmount);
   599→
   600→	switch (Type)
   601→	{
   602→	case ECurrencyType::Coin:
   603→		if (CoinBalance != NewAmount)
   604→		{
   605→			CoinBalance = NewAmount;
   606→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   607→		}
   608→		break;
   609→	case ECurrencyType::Gem:
   610→		if (GemBalance != NewAmount)
   611→		{
   612→			GemBalance = NewAmount;
   613→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   614→		}
   615→		break;
   616→	}
   617→}
