void ShowNotification(const FText& Message, bool bSuccess);

/** 알림 숨기기 */
void HideNotification();

/** 알림 자동 숨기기 타이머 */
FTimerHandle NotificationTimerHandle;

/** 알림 표시 시간 (초) */
